-- ═══════════════════════════════════════════════════════════════════════════════════════════════
-- 0047 — THE SEA IS A FREE PLANE
--        ONE mover over open water. The client PROPOSES a course; the server VERIFIES it against
--        its own raster, MEASURES it itself, and sails it. Any water point is a destination.
-- ═══════════════════════════════════════════════════════════════════════════════════════════════
--
-- GENERATED by scripts/gen-0047.mjs against the live chain (the slice-and-replace method: every
-- superseded body is edited by hunks that must occur EXACTLY ONCE in the deployed definition,
-- re-asserted at apply time — a drifted deployment refuses rather than half-applies).
--
-- ── THE ASK (docs/OWNER_REQUESTS.md rows 41-43; docs/NAVIGATION_PLAN.md is the approved plan) ──
-- The owner, three times: "it should go by sea without the fixed route — but fastest way
-- possible. Also, in map, i should be able to pinpoint anywhere in the ocean to make a fleet
-- move." The fixed 782-leg graph routed Lisboa→Nagasaki over the North Pole at 88.6°N for 7,565
-- nm (the honest water is ~12,989 round the Cape), drew 532 of its legs over land, and silently
-- teleported 41 river-port approaches. One wrong model, five logged defects.
--
-- ── THE DESIGN, measured not chosen (NAVIGATION_PLAN §3) ───────────────────────────────────────
-- A* in plpgsql costs 302 s for Lisboa→Calicut; the same search in the browser costs ≤166 ms;
-- VERIFYING a path is all water costs 0.02 ms. So the search runs where it is cheap (the client,
-- src/lib/sea — a PROPOSAL), and the authoritative acts run here: voyage.path_refusal samples
-- every segment against public.sea_raster (0046), voyage.path_nm measures the polyline, and the
-- refusal gates (crew, flagship, draft, ice, endurance) stay ONE authority. A client cannot gain
-- by lying: land is refused, a longer course only costs its own player days and stores, and a
-- shorter water-legal course is simply a better route. With no course attached, the straight
-- line is tried (free, and correct exactly when it verifies); otherwise E_NO_COURSE.
--
-- ── REPLACES — never joins (the predecessor's catastrophe was four overlapping movement paths) ──
--   voyage.route, voyage.route_direct, voyage.path_from_nodes    DROPPED — the graph mover
--   voyage.reach_from(uuid, int, uuid)   DROPPED; reach_from(uuid) reads sea_reaches (0046)
--   voyage.sail_refusal(uuid, uuid, numeric)   DROPPED; (fleet, dest, dest_point, nm) supersedes
--       0036's body whole: same gates, and the no-chandler round-trip rule now prices a bare
--       water point (the way back is the way she came) as well as a sea place (nearest harbour
--       by the reach table).
--   voyage.depart(uuid, uuid[], timestamptz)   DROPPED; depart(fleet, segments, origin, dest)
--   voyage.position   DROPPED and re-cut: the point is placed linearly along the SEGMENT — the
--       same interpolation path_refusal samples, so the line judged, sailed and drawn is one.
--   cmd.do_sail   re-cut whole (0019's body): verify → measure → gate → depart.
--   cmd.divert(uuid, uuid)   DROPPED; (fleet, dest, dest_point, path) supersedes 0037: she turns
--       AT HER POSITION (truncate, settle to anchor through the one arrival arm, clear the
--       stale queue, one SAIL through the one parser). 0037's node-turn existed only because
--       routing from a point was impossible; it is not any more.
--   cmd.issue / cmd.preview   DROPPED and re-cut with p_path jsonb (the proposed course rides
--       the ARGS and is verified at execution); preview accepts ANCHORED.
--   world.trade_routes   DROPPED and re-cut: the scan radius is SAILED NM over sea_reaches
--       (sea_scan_radius_nm, default 1,700 = the measured median horizon of the old 2-leg scan),
--       and every quoted nm is now honest water — the Asian trade stops being priced at half its
--       true distance.
--   voyage.settle   SLICED (2 hunks): the arrival arm anchors an open-water end (ANCHORED,
--       lat/lon held) and the report carries from_point/to_point. Wage/ration/hazard arithmetic
--       untouched BY CONSTRUCTION — the slices are the only change, occurs-exactly-once.
--   cmd.advance   SLICED (1 hunk): ANCHORED runs the queue (quay verbs still refuse themselves).
--   cmd.parse   SLICED: SAIL takes a port OR a lat,lon point; VIA retired with the graph.
--   cmd.verb_schema   SLICED: SAIL's dest is type "place"; the composer renders it.
--   world.snapshot   SLICED: the legs block is gone from the wire.
--   world.fleets   SLICED (2 hunks): fleets carry anchor; a voyage serves its whole course,
--       dest_point, and the re-cut position shape.
--   public.client_rpc_entry_points   re-cut whole: issue/preview/divert/trade_routes signatures,
--       plus world.sea_raster and world.reach.
--
-- ── WHAT SURVIVES UNTOUCHED, deliberately ──────────────────────────────────────────────────────
--   voyage.progress_nm / sim_hours / total_days / day_ends_at / delay_before_day / recompute_eta
--   / rng / hazard_roll / leg_at_day — they read only 'nm', 'sea_id', 'hazard_mult', which every
--   new segment carries under the same names. A computed course is still a FIXED course once
--   departed: speed_profile freezes per segment and proof 01's offline equivalence rests exactly
--   where 0006 put it. THE WIND SEAM: a segment has a bearing, so the coming wind slice
--   multiplies the per-segment frozen speed inside voyage.depart by a pure function of
--   (segment, season, world secret) — nothing else will have to move. public.legs stays as
--   history for the moment, with no reader left in the mover — 0049 (the graph is history)
--   drops the table itself: a table nobody reads is drift waiting to be trusted.
--
-- ── CARRIED FORWARD ────────────────────────────────────────────────────────────────────────────
--   Pre-0047 voyages store leg REFERENCES; they are converted in place to legacy-marked segments
--   (same nm, same seas, same frozen speeds — the schedule is byte-identical) so every reader
--   speaks one shape. The land guard reports legacy paths rather than walking them: a straight
--   line between two ports is exactly the shape the old model drew and the new one forbids.
-- ═══════════════════════════════════════════════════════════════════════════════════════════════

-- ── 0. The slice tool: replace hunks that must occur exactly once, else refuse ─────────────────
create or replace function pg_temp.recut(p_fn regprocedure, p_drop boolean, variadic p_edits text[])
returns void
language plpgsql
as $$
declare
  v_def text := pg_get_functiondef(p_fn);
  v_i   int := 1;
  v_n   int;
begin
  while v_i < array_length(p_edits, 1) loop
    v_n := (length(v_def) - length(replace(v_def, p_edits[v_i], ''))) / length(p_edits[v_i]);
    if v_n <> 1 then
      raise exception '0047 slice: hunk % of % occurs % time(s) in %, expected exactly 1 — the deployed body is not what this migration was generated against. Regenerate with scripts/gen-0047.mjs.',
        (v_i + 1) / 2, (array_length(p_edits, 1)) / 2, v_n, p_fn;
    end if;
    v_def := replace(v_def, p_edits[v_i], p_edits[v_i + 1]);
    v_i := v_i + 2;
  end loop;
  if p_drop then
    execute format('drop function %s', p_fn::text);
  end if;
  execute v_def;
end $$;

-- ── 1. The knobs ───────────────────────────────────────────────────────────────────────────────
insert into public.world_config (key, value, description) values
  ('course_join_nm', to_jsonb(15),
   '0047: how far a proposed course''s first/last point may sit from the stated origin/destination (and how far a divert''s course may start from the fleet''s true position before the bridge is prepended). One raster cell is ~15 nm at the equator.'),
  ('sea_scan_radius_nm', to_jsonb(1700),
   '0047: how far out, in SAILED nautical miles over sea_reaches, world.trade_routes looks by default. 1,700 is measured, not chosen: the median horizon of the old 2-leg leg-graph scan across all 214 harbours was 1,669 nm (median 14 destinations). Replaces route_scan_max_legs.')
on conflict (key) do nothing;

-- The 2-leg knob has no reader left; a knob nobody reads is drift waiting to be trusted.
delete from public.world_config where key = 'route_scan_max_legs';

-- ── 2. A fleet can hold a POSITION: the anchor columns and the one status/position law ─────────
alter table public.fleets add column if not exists lat numeric, add column if not exists lon numeric;

do $$
declare v_name text;
begin
  -- 0004's inline position check said "not SAILING means in a port", which ANCHORED breaks.
  -- It was unnamed, so it is found by its own definition rather than by a guessed name.
  select conname into v_name
    from pg_constraint
   where conrelid = 'public.fleets'::regclass and contype = 'c'
     and pg_get_constraintdef(oid) like '%port_id%' and pg_get_constraintdef(oid) like '%SAILING%';
  if v_name is null then
    raise exception '0047 self-assert FAIL: the 0004 fleet position check was not found to supersede';
  end if;
  execute format('alter table public.fleets drop constraint %I', v_name);
end $$;

alter table public.fleets add constraint fleets_position_states check (
  case status
    when 'SAILING'  then port_id is null and lat is null and lon is null
    when 'ANCHORED' then port_id is null and lat is not null and lon is not null
    when 'DOCKED'   then port_id is not null and lat is null and lon is null
    when 'REPAIRING' then port_id is not null and lat is null and lon is null
    -- UNABLE_TO_SAIL / ADRIFT: wherever it happened — a berth, or a held position
    else (port_id is not null and lat is null and lon is null)
      or (port_id is null and lat is not null and lon is not null)
  end);

-- A voyage's ends may now be open water: the port references become nullable; the path itself
-- always carries the coordinates.
alter table public.voyages alter column origin_port_id drop not null,
                           alter column dest_port_id drop not null;

-- ── 3. THE SEAM: which sea is this point in? — COMPOSED, never duplicated ──────────────────────
-- 0040 (every water answers its sea) already holds THE membership authority:
-- voyage.sea_at(lat, lon) over public.sea_cells, boundaries from Natural Earth's marine
-- polygons. The helm cut of this migration shipped an interim nearest-port body and declared
-- the signature a seam for exactly that slice to fill; it landed first here, so this file
-- creates NOTHING for membership — it COMPOSES. What a course segment needs beyond sea_at is
-- tolerance for its own approach: sea_at is strict (null on land, and a harbour's cell is
-- usually land at this resolution), while every segment must carry a sea or hazards lose
-- their spatial dimension. So:
--   voyage.sea_near(lat, lon)  the sea AT the point, else the nearest claimed water by
--                              expanding ring over cell centres — the same 8-ring rule 0040's
--                              own self-assert resolves ports with — each probe answered by
--                              voyage.sea_at itself. It raises beyond 8 rings: a verified
--                              water course through sea nobody claims is a world defect, and
--                              it must never ship as a silent null.
-- Consumers: voyage.segments_from_course (hazard sea per segment); the coming NPC-region
-- system reads voyage.sea_at directly (a fleet at anchor holds a strict water point).
create or replace function voyage.sea_near(p_lat double precision, p_lon double precision)
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_sea  uuid;
  v_ring int; v_dr int; v_dc int;
begin
  v_sea := voyage.sea_at(p_lat, p_lon);
  if v_sea is not null then return v_sea; end if;
  for v_ring in 1 .. 8 loop
    for v_dr in -v_ring .. v_ring loop
      for v_dc in -v_ring .. v_ring loop
        continue when greatest(abs(v_dr), abs(v_dc)) <> v_ring;
        v_sea := voyage.sea_at(p_lat + v_dr * 0.25, p_lon + v_dc * 0.25);
        if v_sea is not null then return v_sea; end if;
      end loop;
    end loop;
  end loop;
  raise exception 'E_NO_SEA: no sea claims the water near %, % within 8 rings — the membership raster (0040) and the passability raster (0046) disagree here', round(p_lat::numeric, 2), round(p_lon::numeric, 2) using errcode = 'P0001';
end $$;

revoke all on function voyage.sea_near(double precision, double precision) from public, anon, authenticated;

-- How far a coordinate sits from sailable water — the MEASURED approach allowance for a course
-- end that is not a port (a fleet's own position, a pinpointed spot). A port's figure lives in
-- sea_reaches.snap_nm, measured the same way at generation; this is the same rule at runtime,
-- so an end's exemption is never a guess. Found the expensive way: a fleet minutes out of
-- Lisboa still stands INSIDE Lisboa's approach — where her verified course legitimately crosses
-- land cells — and a flat 25 nm allowance refused her own turn as E_LAND.
create or replace function voyage.water_snap_nm(p_lat numeric, p_lon numeric)
returns numeric
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  r public.sea_raster%rowtype;
  v_row int; v_col int; ring int; dr int; dc int; rr int; cc int;
  v_best numeric := null;
  v_nm numeric;
begin
  select * into r from public.sea_raster where id = 1;
  v_row := least(r.rows - 1, greatest(0, floor((90 - p_lat) / r.cell_deg)::int));
  v_col := ((floor((p_lon + 180) / r.cell_deg)::int % r.cols) + r.cols) % r.cols;
  if get_bit(r.cells, (v_row * r.cols + v_col) * r.bits_per_cell) = 1 then
    return 0;
  end if;
  for ring in 1 .. 12 loop
    for dr in -ring .. ring loop
      rr := v_row + dr;
      continue when rr < 0 or rr >= r.rows;
      for dc in -ring .. ring loop
        continue when greatest(abs(dr), abs(dc)) <> ring;
        cc := ((v_col + dc) % r.cols + r.cols) % r.cols;
        if get_bit(r.cells, (rr * r.cols + cc) * r.bits_per_cell) = 1 then
          v_nm := voyage.gc_distance_nm(p_lat::float8, p_lon::float8,
                    (90 - (rr + 0.5) * r.cell_deg)::float8, (-180 + (cc + 0.5) * r.cell_deg)::float8)::numeric;
          if v_best is null or v_nm < v_best then v_best := v_nm; end if;
        end if;
      end loop;
    end loop;
    exit when v_best is not null;
  end loop;
  return coalesce(v_best, 999);
end $$;

revoke all on function voyage.water_snap_nm(numeric, numeric) from public, anon, authenticated;

-- ── 4. A verified course becomes THE stored path: segments that carry their own water ──────────
create or replace function voyage.segments_from_course(p_course jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
-- One segment per sub-leg of the polyline, each carrying:
--   nm           its own length (the measure's rule, per piece — the stored total is their sum)
--   sea_id       voyage.sea_near at the midpoint (0040's sea_at composed with the 8-ring
--                approach tolerance), so free water keeps hazard's spatial dimension
--   hazard_mult  SHELTER, derived from the raster: land (or ice) within ~2 cells 0.8 — in sight
--                of refuge; none within ~7 cells 1.2 — days from shelter; else 1.0. The old
--                leg-graph texture keyed on authored endpoints; free segments key on the one
--                fact the raster knows. Sea character (piracy, base rate) stays in seas.*.
-- Segments over 500 nm are SPLIT into equal parts, so an ocean crossing changes sea and shelter
-- as it goes instead of wearing one midpoint's answer for 3,000 nm.
declare
  r        public.sea_raster%rowtype;
  out_segs jsonb := '[]'::jsonb;
  i int; k int; n int; pieces int;
  lat1 float8; lon1 float8; lat2 float8; lon2 float8;
  alat float8; alon float8; blat float8; blon float8;
  seg_nm numeric; mlat float8; mlon float8;
  v_row int; v_col int; ring int; dr int; dc int; rr int; cc int;
  v_land_ring int;
begin
  select * into r from public.sea_raster where id = 1;
  n := coalesce(jsonb_array_length(p_course), 0);
  for i in 0 .. n - 2 loop
    lat1 := (p_course->i->>0)::float8;     lon1 := (p_course->i->>1)::float8;
    lat2 := (p_course->(i+1)->>0)::float8; lon2 := (p_course->(i+1)->>1)::float8;
    pieces := greatest(1, ceil(voyage.gc_distance_nm(lat1, lon1, lat2, lon2) / 500)::int);
    for k in 0 .. pieces - 1 loop
      alat := lat1 + (lat2 - lat1) * k / pieces;       alon := lon1 + (lon2 - lon1) * k / pieces;
      blat := lat1 + (lat2 - lat1) * (k + 1) / pieces; blon := lon1 + (lon2 - lon1) * (k + 1) / pieces;
      seg_nm := round(voyage.gc_distance_nm(alat, alon, blat, blon)::numeric, 2);
      continue when seg_nm <= 0;
      mlat := (alat + blat) / 2; mlon := (alon + blon) / 2;
      v_row := least(r.rows - 1, greatest(0, floor((90 - mlat) / r.cell_deg)::int));
      v_col := ((floor((mlon + 180) / r.cell_deg)::int % r.cols) + r.cols) % r.cols;
      v_land_ring := null;
      for ring in 1 .. 7 loop
        for dr in -ring .. ring loop
          rr := v_row + dr;
          continue when rr < 0 or rr >= r.rows;
          for dc in -ring .. ring loop
            continue when greatest(abs(dr), abs(dc)) <> ring;
            cc := ((v_col + dc) % r.cols + r.cols) % r.cols;
            if get_bit(r.cells, (rr * r.cols + cc) * r.bits_per_cell) = 0 then
              v_land_ring := ring;
              exit;
            end if;
          end loop;
          exit when v_land_ring is not null;
        end loop;
        exit when v_land_ring is not null;
      end loop;
      out_segs := out_segs || jsonb_build_object(
        'a', jsonb_build_array(round(alat::numeric, 4), round(alon::numeric, 4)),
        'b', jsonb_build_array(round(blat::numeric, 4), round(blon::numeric, 4)),
        'nm', seg_nm,
        'sea_id', voyage.sea_near(mlat, mlon),
        'hazard_mult', case when v_land_ring is not null and v_land_ring <= 2 then 0.8
                            when v_land_ring is null then 1.2
                            else 1.0 end);
    end loop;
  end loop;
  return out_segs;
end $$;

revoke all on function voyage.segments_from_course(jsonb) from public, anon, authenticated;

-- The polyline a stored path sails: first segment's a, then every b, in order. Serves the chart
-- (world.fleets) and the land guard; ONE reading of "what line is this voyage on".
create or replace function voyage.course_of(p_path jsonb)
returns jsonb
language sql
immutable
as $$
  select case when p_path is null or jsonb_array_length(p_path) = 0 then '[]'::jsonb
              else jsonb_build_array(p_path->0->'a')
                   || (select coalesce(jsonb_agg(t.s->'b' order by t.ord), '[]'::jsonb)
                         from jsonb_array_elements(p_path) with ordinality t(s, ord))
         end
$$;

-- ── 5. The graph mover is DROPPED — one mover, never two ───────────────────────────────────────
drop function voyage.route(uuid, uuid, uuid[]);
drop function voyage.route_direct(uuid, uuid);
drop function voyage.path_from_nodes(uuid[]);
drop function voyage.reach_from(uuid, int, uuid);
drop function voyage.sail_refusal(uuid, uuid, numeric);
drop function voyage.depart(uuid, uuid[], timestamptz);
drop function voyage.position(uuid, timestamptz);
drop function cmd.divert(uuid, uuid);

-- ── 6. THE sailed distance, from the reach table (0046) ────────────────────────────────────────
create or replace function voyage.reach_from(p_from uuid)
returns table (port_id uuid, code text, nm numeric)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- Supersedes 0019's graph Dijkstra: the figures come from public.sea_reaches — computed from
  -- the raster by the one pathfinder, Arctic closed, no Suez, no Panama — so the number a quay
  -- quotes and the water a fleet sails can no longer be two different worlds.
  select b.port_id, e.code, e.nm::numeric
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.sea_reaches b on b.code = e.code
   where a.port_id = p_from
$$;

revoke all on function voyage.reach_from(uuid) from public, anon, authenticated;

-- ── 7. THE one answer to "may this fleet sail there?" ──────────────────────────────────────────
create or replace function voyage.sail_refusal(p_fleet uuid, p_dest uuid, p_dest_point jsonb, p_nm numeric)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
-- Supersedes 0036's leg-graph body (dropped above). What changed and what did not:
--   * she may sail from a quay OR from her own anchor — the sea is a free plane;
--   * draft and ice-closure are asked only of a HARBOUR destination: they are berth facts, and
--     open water has neither;
--   * the stores gate: a destination with a chandler needs stores for the passage; one WITHOUT
--     (a sea place, or any bare point of water) needs the ROUND TRIP — out, plus the way back
--     to provisioning: a sea place's nearest harbour by the reach table, or for a bare point
--     the way she came, which is the one water she is PROVEN able to sail. Same one-way-trap
--     rule 0036 wrote for spur legs, priced off the reach table.
declare
  f       public.fleets%rowtype;
  v_short int;
  v_flag  numeric;
  v_draft int;
  v_maxd  int;
  v_kind  text;
  v_speed numeric;
  v_days  numeric;
  v_end   numeric;
  v_back  numeric := 0;
begin
  select * into f from public.fleets where id = p_fleet;
  if f.id is null then
    return 'E_NO_SUCH_FLEET: there is no such fleet';
  end if;
  if f.status not in ('DOCKED', 'ANCHORED') then
    return format('E_NOT_DOCKED: %s is %s and must be docked or lying at anchor to sail', f.name, f.status);
  end if;

  select count(*) into v_short
    from public.ships s join public.ship_classes c on c.id = s.class_id
   where s.fleet_id = p_fleet and s.crew < c.crew_required;
  if v_short > 0 then
    return format('E_CREW_SHORT: %s ship(s) are below their required complement', v_short);
  end if;

  select coalesce(durability, 0) into v_flag from public.ships where fleet_id = p_fleet and is_flagship;
  if coalesce(v_flag, 0) <= 0 then
    return 'E_FLAGSHIP_DISABLED: the flagship cannot sail until it is repaired';
  end if;

  if p_dest is not null then
    select kind into v_kind from public.ports where id = p_dest;
    if v_kind = 'HARBOUR' then
      select max(c.draft) into v_draft from public.ships s join public.ship_classes c on c.id = s.class_id
       where s.fleet_id = p_fleet;
      select max_draft into v_maxd from public.ports where id = p_dest;
      if v_draft > v_maxd then
        return format('E_DRAFT: the deepest hull draws %s and that port takes %s', v_draft, v_maxd);
      end if;
      if (select is_ice_closed from public.ports where id = p_dest) then
        return 'E_PORT_CLOSED: that port is closed';
      end if;
    end if;
  end if;

  v_speed := voyage.fleet_speed(p_fleet);
  v_end   := voyage.endurance_days(p_fleet);
  if p_dest is not null and (select kind from public.ports where id = p_dest) = 'SEA_PLACE' then
    select min(e.nm::numeric) into v_back
      from public.sea_reaches sr
     cross join lateral jsonb_each_text(sr.reaches) e(code, nm)
      join public.ports hp on hp.code = e.code and hp.kind = 'HARBOUR'
     where sr.port_id = p_dest;
  elsif p_dest is null and p_dest_point is not null then
    v_back := p_nm;
  end if;
  v_days := ((p_nm + coalesce(v_back, 0)) / v_speed) / 24;
  if v_end < v_days * public.wc_num('endurance_margin') then
    if coalesce(v_back, 0) > 0 then
      return format('E_ENDURANCE: %s carries %s days of stores, and there is no chandler where she is bound — the round trip is %s voyage-days; you need %s — PROVISION first',
        f.name, round(v_end, 1), round(v_days, 1), round(v_days * public.wc_num('endurance_margin'), 1));
    end if;
    return format('E_ENDURANCE: %s carries %s days of stores and that route is %s voyage-days; you need %s — PROVISION first',
      f.name, round(v_end, 1), round(v_days, 1), round(v_days * public.wc_num('endurance_margin'), 1));
  end if;
  return null;
end $$;

comment on function voyage.sail_refusal(uuid, uuid, jsonb, numeric) is
  'THE one answer to "may this fleet sail there, right now?" — status, crew, flagship, berth '
  'facts for harbours, and the stores gate with the no-chandler round trip. cmd.do_sail RAISES '
  'what this returns and world.trade_routes refuses to recommend what this refuses. Supersedes '
  '0036''s leg-graph body (0047).';

revoke all on function voyage.sail_refusal(uuid, uuid, jsonb, numeric) from public, anon, authenticated;

-- ── 8. Departure: the ONE place a voyage is born ───────────────────────────────────────────────
create or replace function voyage.depart(p_fleet uuid, p_segments jsonb, p_origin_port uuid, p_dest_port uuid, p_at timestamptz default now())
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
-- Supersedes 0006's node-list body (dropped above). The path is SEGMENTS of verified open water;
-- each keeps the speed frozen for it at departure — THE WIND SEAM: when wind lands, this loop
-- multiplies v_speed by a pure function of (segment, season, world secret) and nothing else in
-- the schedule moves. A computed course is still a FIXED course once departed: closed form,
-- per-element freeze, delays as recorded sim-hours — exactly what proof 01 rests on.
declare
  v_total   numeric := 0;
  v_hours   numeric := 0;
  v_speed   numeric;
  v_profile jsonb := '[]'::jsonb;
  v_player  uuid;
  v_voyage  uuid;
  e         jsonb;
begin
  select player_id into v_player from public.fleets where id = p_fleet;
  if v_player is null then
    raise exception 'E_NO_SUCH_FLEET: %', p_fleet using errcode = 'P0001';
  end if;
  if p_segments is null or jsonb_typeof(p_segments) <> 'array' or jsonb_array_length(p_segments) < 1 then
    raise exception 'E_BAD_PATH: a voyage needs at least one segment of water' using errcode = 'P0001';
  end if;
  v_speed := voyage.fleet_speed(p_fleet);
  for e in select * from jsonb_array_elements(p_segments) loop
    v_profile := v_profile || to_jsonb(v_speed);
    v_total   := v_total + (e->>'nm')::numeric;
    v_hours   := v_hours + (e->>'nm')::numeric / v_speed;
  end loop;

  insert into public.voyages (fleet_id, player_id, path, total_nm, speed_profile, departed_at, eta,
                              origin_port_id, dest_port_id)
  values (p_fleet, v_player, p_segments, v_total, v_profile, p_at,
          p_at + make_interval(secs => (v_hours * 3600 / public.wc_num('time_compression'))::double precision),
          p_origin_port, p_dest_port)
  returning id into v_voyage;

  update public.fleets
     set status = 'SAILING', port_id = null, lat = null, lon = null, version = version + 1
   where id = p_fleet;

  return v_voyage;
end $$;

revoke all on function voyage.depart(uuid, jsonb, uuid, uuid, timestamptz) from public, anon, authenticated;

-- ── 9. The closed-form place on the water ──────────────────────────────────────────────────────
create or replace function voyage.position(p_voyage uuid, p_at timestamptz default now())
returns table (seg_index int, leg_frac numeric, nm_done numeric, total_nm numeric, lat numeric, lon numeric)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
-- Supersedes 0006's port-interpolating body (dropped above). Same rule, new geometry:
-- progress_nm is unchanged, and the point is placed LINEARLY along the segment the progress
-- falls in — the SAME interpolation voyage.path_refusal samples, so the line judged, the line
-- sailed and the point drawn are one line.
declare
  v       public.voyages%rowtype;
  v_done  numeric;
  v_acc   numeric := 0;
  i       int := 0;
  e       jsonb;
  v_nm    numeric;
begin
  select * into v from public.voyages where id = p_voyage;
  if v.id is null then
    raise exception 'E_NO_SUCH_VOYAGE: %', p_voyage using errcode = 'P0001';
  end if;
  v_done := voyage.progress_nm(p_voyage, p_at);
  for e in select * from jsonb_array_elements(v.path) loop
    v_nm := (e->>'nm')::numeric;
    if v_done <= v_acc + v_nm or i = jsonb_array_length(v.path) - 1 then
      seg_index := i;
      leg_frac  := round(least(1, greatest(0, case when v_nm = 0 then 1 else (v_done - v_acc) / v_nm end)), 6);
      nm_done   := v_done;
      total_nm  := v.total_nm;
      lat := round(((e->'a'->>0)::numeric + ((e->'b'->>0)::numeric - (e->'a'->>0)::numeric) * leg_frac), 4);
      lon := round(((e->'a'->>1)::numeric + ((e->'b'->>1)::numeric - (e->'a'->>1)::numeric) * leg_frac), 4);
      return next;
      return;
    end if;
    v_acc := v_acc + v_nm;
    i := i + 1;
  end loop;
end $$;

revoke all on function voyage.position(uuid, timestamptz) from public, anon;
grant execute on function voyage.position(uuid, timestamptz) to authenticated;

-- ── 10. THE ONE MOVER ──────────────────────────────────────────────────────────────────────────
create or replace function cmd.do_sail(p_fleet uuid, p_args jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
-- Supersedes 0019's leg-graph body whole. The client PROPOSES a course (args.path, attached by
-- cmd.issue's p_path); the server VERIFIES it against its own raster and MEASURES it itself —
-- verification is the authoritative act, and no client number is ever believed. With no course
-- attached, the straight line is tried — free, and correct exactly when it verifies — otherwise
-- the order is refused E_NO_COURSE rather than guessed at.
declare
  f         public.fleets%rowtype;
  v_dest    uuid := nullif(p_args->>'dest', '')::uuid;
  v_point   jsonb := p_args->'dest_point';
  v_course  jsonb := p_args->'path';
  v_plotted boolean := coalesce(jsonb_typeof(p_args->'path') = 'array', false);
  v_olat numeric; v_olon numeric; v_head numeric;
  v_dlat numeric; v_dlon numeric; v_tail numeric;
  v_ref    text;
  v_nm     numeric;
  v_segs   jsonb;
  v_speed  numeric;
  v_voyage uuid;
begin
  select * into f from public.fleets where id = p_fleet;

  -- the gates that need no distance, first (status, crew, flagship, and the berth facts)
  v_ref := voyage.sail_refusal(p_fleet, v_dest, v_point, 0);
  if v_ref is not null then
    raise exception '%', v_ref using errcode = 'P0001';
  end if;

  -- where she lies: a quay, or her own anchor. The approach allowance is the MEASURED snap of
  -- the place plus 25 nm slack — the same rule (snap + one cell) the client's straightener
  -- applies, held slightly looser here so a course the client passed cannot be refused for its
  -- own approach.
  if f.port_id is not null then
    select p.lat, p.lon into v_olat, v_olon from public.ports p where p.id = f.port_id;
    v_head := coalesce((select snap_nm from public.sea_reaches where port_id = f.port_id), 0) + 25;
  else
    -- her own position: the approach is MEASURED, not guessed — a fleet minutes off a river
    -- quay still stands inside that port's approach, where her verified course crosses land
    -- cells, and a flat allowance refused her own turn as E_LAND (the acceptance drive).
    v_olat := f.lat; v_olon := f.lon;
    v_head := voyage.water_snap_nm(v_olat, v_olon) + 25;
  end if;

  -- where she is bound
  if v_dest is not null then
    if v_dest = f.port_id then
      raise exception 'E_SAME_DEST: % already lies there', f.name using errcode = 'P0001';
    end if;
    select p.lat, p.lon into v_dlat, v_dlon from public.ports p where p.id = v_dest;
    if v_dlat is null then
      raise exception 'E_NO_SUCH_PORT: there is no such port' using errcode = 'P0001';
    end if;
    v_tail := coalesce((select snap_nm from public.sea_reaches where port_id = v_dest), 0) + 25;
  elsif v_point is not null then
    v_dlat := (v_point->>'lat')::numeric; v_dlon := (v_point->>'lon')::numeric;
    if v_dlat is null or v_dlon is null or abs(v_dlat) > 90 or abs(v_dlon) > 180 then
      raise exception 'E_BAD_PATH: that is not a point on the sphere' using errcode = 'P0001';
    end if;
    v_tail := voyage.water_snap_nm(v_dlat, v_dlon) + 25;
    if voyage.gc_distance_nm(v_olat::float8, v_olon::float8, v_dlat::float8, v_dlon::float8)
         <= public.wc_num('course_join_nm') then
      raise exception 'E_SAME_DEST: % already lies there', f.name using errcode = 'P0001';
    end if;
  else
    raise exception 'E_PARSE: SAIL needs a destination - a port, or a lat,lon point of open sea' using errcode = 'P0001';
  end if;

  -- the course: proposed, or the straight line when none was
  if not v_plotted then
    v_course := jsonb_build_array(jsonb_build_array(v_olat, v_olon), jsonb_build_array(v_dlat, v_dlon));
  end if;
  v_ref := voyage.path_refusal(v_course, v_olat, v_olon, v_dlat, v_dlon,
                               public.wc_num('course_join_nm'), v_head, v_tail);
  if v_ref is not null then
    if not v_plotted and v_ref like 'E_LAND:%' then
      raise exception 'E_NO_COURSE: the straight way is not open water - the chart plots the course at the moment of ordering' using errcode = 'P0001';
    end if;
    raise exception '%', v_ref using errcode = 'P0001';
  end if;

  -- THE MEASURE - the server's own, never the client's
  v_segs := voyage.segments_from_course(v_course);
  select sum((s->>'nm')::numeric) into v_nm from jsonb_array_elements(v_segs) s;

  v_ref := voyage.sail_refusal(p_fleet, v_dest, v_point, v_nm);
  if v_ref is not null then
    raise exception '%', v_ref using errcode = 'P0001';
  end if;

  v_speed := voyage.fleet_speed(p_fleet);
  v_voyage := voyage.depart(p_fleet, v_segs, f.port_id, v_dest);
  perform public.emit_event(f.player_id, 'DEPARTED', jsonb_build_object(
    'fleet', f.name, 'voyage_id', v_voyage, 'total_nm', v_nm,
    'points', jsonb_array_length(v_course),
    'dest', coalesce((select code from public.ports where id = v_dest),
                     format('%s,%s', round(v_dlat, 2), round(v_dlon, 2))),
    'eta', (select eta from public.voyages where id = v_voyage)));
  return jsonb_build_object('voyage_id', v_voyage, 'total_nm', v_nm,
                            'voyage_days', round((v_nm / v_speed) / 24, 2));
end $$;

revoke all on function cmd.do_sail(uuid, jsonb) from public, anon, authenticated;

-- ── 11. Pre-0047 voyages are carried forward: leg references become legacy segments ────────────
create or replace function voyage.convert_leg_path(p_path jsonb)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- Each leg becomes one segment with the SAME nm, sea and hazard weight — the frozen contract
  -- (nm and per-element speeds are what the schedule is made of) is untouched to the byte — its
  -- endpoints the two ports' coordinates, and a 'legacy' mark: a straight line between ports is
  -- exactly the shape the old model drew, so the land guard reports these rather than walks them.
  select coalesce(jsonb_agg(jsonb_build_object(
           'a', jsonb_build_array(pa.lat, pa.lon),
           'b', jsonb_build_array(pb.lat, pb.lon),
           'nm', (t.e->>'nm')::numeric,
           'sea_id', t.e->'sea_id',
           'hazard_mult', t.e->'hazard_mult',
           'legacy', true) order by t.ord), '[]'::jsonb)
    from jsonb_array_elements(p_path) with ordinality t(e, ord)
    join public.ports pa on pa.id = (t.e->>'from_id')::uuid
    join public.ports pb on pb.id = (t.e->>'to_id')::uuid
$$;

revoke all on function voyage.convert_leg_path(jsonb) from public, anon, authenticated;

do $$
declare v_old int; v_left int;
begin
  -- MEASURED DELTA, not a bare count: how many the world held, and none left behind.
  select count(*) into v_old from public.voyages where path->0 ? 'leg_id';
  update public.voyages set path = voyage.convert_leg_path(path) where path->0 ? 'leg_id';
  select count(*) into v_left from public.voyages where path->0 ? 'leg_id';
  if v_left <> 0 then
    raise exception '0047 self-assert FAIL: % voyage(s) still carry leg-shaped paths after conversion', v_left;
  end if;
  raise notice '0047 carry-forward: % pre-0047 voyage path(s) converted to legacy-marked segments', v_old;
end $$;

-- ── 12. The slices: six live bodies, edited by exactly-once hunks ──────────────────────────────
select pg_temp.recut('voyage.settle(uuid, timestamptz)'::regprocedure, false,
  $sdo$    update public.fleets
       set status = case when (select durability from public.ships where fleet_id = p_fleet and is_flagship) <= 0
                         then 'UNABLE_TO_SAIL' else 'DOCKED' end,
           port_id = v.dest_port_id, version = version + 1
     where id = p_fleet;$sdo$,
  $sdn$    -- 0047: she docks at a HARBOUR or a SEA PLACE; at a bare point of water she comes to ANCHOR,
    -- holding the exact coordinate her course ends at. UNABLE_TO_SAIL still outranks both, and an
    -- open-water end keeps its position either way.
    update public.fleets
       set status = case when (select durability from public.ships where fleet_id = p_fleet and is_flagship) <= 0
                         then 'UNABLE_TO_SAIL'
                         when v.dest_port_id is null then 'ANCHORED'
                         else 'DOCKED' end,
           port_id = v.dest_port_id,
           lat = case when v.dest_port_id is null then (v.path->(jsonb_array_length(v.path)-1)->'b'->>0)::numeric end,
           lon = case when v.dest_port_id is null then (v.path->(jsonb_array_length(v.path)-1)->'b'->>1)::numeric end,
           version = version + 1
     where id = p_fleet;$sdn$,
  $sro$      'from', (select code from public.ports where id = v.origin_port_id),
      'to',   (select code from public.ports where id = v.dest_port_id),$sro$,
  $srn$      'from', (select code from public.ports where id = v.origin_port_id),
      'to',   (select code from public.ports where id = v.dest_port_id),
      -- 0047: an open-water end has no code; the report carries the point instead, and a screen
      -- prints the coordinate rather than inventing a name for nowhere.
      'from_point', case when v.origin_port_id is null then v.path->0->'a' end,
      'to_point',   case when v.dest_port_id  is null then v.path->(jsonb_array_length(v.path)-1)->'b' end,$srn$);

select pg_temp.recut('cmd.advance(uuid, timestamptz)'::regprocedure, false,
  $avo$    exit when f.status <> 'DOCKED';   -- SAILING / ADRIFT / UNABLE_TO_SAIL: nothing can execute$avo$,
  $avn$    -- 0047: a fleet ANCHORED at a point of open water runs her queue too — that is how a queued
    -- onward SAIL departs from a pinpointed spot. Every verb that needs a quay refuses her itself
    -- (E_NOT_DOCKED), so nothing a chandler sells can be conjured at sea by this line.
    exit when f.status not in ('DOCKED', 'ANCHORED');   -- SAILING / ADRIFT / UNABLE_TO_SAIL: nothing can execute$avn$);

select pg_temp.recut('cmd.parse(uuid, uuid, text)'::regprocedure, false,
  $pso$  if v_verb = 'SAIL' then
    -- Keywords TO / VIA are noise-tolerant (DESIGN F.1): omitting them is accepted.
    while i <= n and upper(cmd.fold(t[i])) = 'TO' loop i := i + 1; end loop;
    if i > n then
      raise exception 'E_PARSE: SAIL needs a destination port' using errcode = 'P0001';
    end if;
    v_args := jsonb_build_object('dest', cmd.resolve_port(t[i]));
    i := i + 1;
    while i <= n loop
      if upper(cmd.fold(t[i])) = 'VIA' then i := i + 1; continue; end if;
      v_via := v_via || to_jsonb(cmd.resolve_port(t[i])::text);
      i := i + 1;
    end loop;
    v_args := v_args || jsonb_build_object('via', v_via);
$pso$,
  $psn$  if v_verb = 'SAIL' then
    -- Keyword TO is noise-tolerant (DESIGN F.1): omitting it is accepted. 0047: the destination
    -- is a HARBOUR (a port token) or ANY POINT OF OPEN SEA, written lat,lon in decimal degrees
    -- ("SAIL TO 33,-15") — the map writes that token when the player pinpoints the water. VIA is
    -- retired WITH the leg graph it belonged to: a course is proposed as a polyline by the chart
    -- at the moment of ordering, not spelt port by port, so trailing tokens are a parse error
    -- rather than silently swallowed waypoints (docs/NO_SPAGHETTI.md 7C).
    while i <= n and upper(cmd.fold(t[i])) = 'TO' loop i := i + 1; end loop;
    if i > n then
      raise exception 'E_PARSE: SAIL needs a destination - a port, or a lat,lon point of open sea' using errcode = 'P0001';
    end if;
    if t[i] ~ '^-?[0-9]+(\.[0-9]+)?,-?[0-9]+(\.[0-9]+)?$' then
      v_args := jsonb_build_object('dest_point', jsonb_build_object(
                  'lat', split_part(t[i], ',', 1)::numeric,
                  'lon', split_part(t[i], ',', 2)::numeric));
      if abs((v_args->'dest_point'->>'lat')::numeric) > 90
         or abs((v_args->'dest_point'->>'lon')::numeric) > 180 then
        raise exception 'E_PARSE: "%" is not a point on the sphere', t[i] using errcode = 'P0001';
      end if;
    else
      v_args := jsonb_build_object('dest', cmd.resolve_port(t[i]));
    end if;
    i := i + 1;
    if i <= n then
      raise exception 'E_PARSE: SAIL takes one destination; "%" was left over', t[i] using errcode = 'P0001';
    end if;
$psn$);

select pg_temp.recut('cmd.verb_schema()'::regprocedure, false,
  $vso$    {"verb":"SAIL","args":[
       {"name":"fleet","type":"fleet","required":false},
