select pg_temp.recut('world.trade_routes(uuid, uuid, int, int, uuid)'::regprocedure, true,
  $tr0$FUNCTION world.trade_routes(p_from uuid, p_fleet uuid DEFAULT NULL::uuid, p_max_legs integer DEFAULT NULL::integer, p_limit integer DEFAULT NULL::integer, p_to uuid DEFAULT NULL::uuid)$tr0$,
  $tr1$FUNCTION world.trade_routes(p_from uuid, p_fleet uuid DEFAULT NULL::uuid, p_radius_nm numeric DEFAULT NULL::numeric, p_limit integer DEFAULT NULL::integer, p_to uuid DEFAULT NULL::uuid)$tr1$,
  $tr2$  v_legs    int     := greatest(1, coalesce(p_max_legs, public.wc_int('route_scan_max_legs')));$tr2$,
  $tr3$  v_radius  numeric := greatest(1, coalesce(p_radius_nm, public.wc_num('sea_scan_radius_nm')));$tr3$,
  $tr4$    select r.port_id, r.nm, r.hops
      from voyage.reach_from(p_from, case when p_to is null then v_ports else null end) r
     where (case when p_to is null then (r.hops between 1 and v_legs)
                 else (r.port_id = p_to) end)
       -- A DESTINATION THIS FLEET COULD NOT SAIL TO IS NOT A RECOMMENDATION. The gate is
       -- voyage.sail_refusal — the SAME authority cmd.do_sail raises from — so the quay cannot
       -- name a port the order would refuse. Applied only when she is lying here: a fleet at sea
       -- has no current sailing to judge, so the scan falls back to the stated default basis.
       -- The gate is her CURRENT lading: taking cargo aboard slows her, so a route within a few
       -- per cent of her endurance can still be refused once loaded (see the header).
       and (v_basis <> 'fleet' or voyage.sail_refusal(p_fleet, r.port_id, r.nm) is null)
$tr4$,
  $tr5$    -- 0047: the reach is the SAILED DISTANCE TABLE (sea_reaches, derived from the raster by the
    -- one pathfinder), not the leg graph. "Two legs out" becomes a radius in nautical miles —
    -- sea_scan_radius_nm defaults to 1,700, the measured median horizon of the old 2-leg scan
    -- across all 214 harbours — and the gate is the same one authority cmd.do_sail raises from.
    select y.port_id, y.nm
      from (select r.port_id, r.nm
              from voyage.reach_from(p_from) r
              join public.ports dp on dp.id = r.port_id and dp.kind = 'HARBOUR'
             where (p_to is null and r.nm <= v_radius) or (r.port_id = p_to)
             order by r.nm, r.port_id
             limit v_ports) y
     where (v_basis <> 'fleet' or voyage.sail_refusal(p_fleet, y.port_id, null, y.nm) is null)
$tr5$,
  $tr6$    select h.good_id, rc.port_id, rc.nm, rc.hops, h.mid as mid_here,$tr6$,
  $tr7$    select h.good_id, rc.port_id, rc.nm, h.mid as mid_here,$tr7$,
  $tr8$    select m.good_id, m.port_id, m.nm, m.hops, m.mid_there - m.mid_here as gap,$tr8$,
  $tr9$    select m.good_id, m.port_id, m.nm, m.mid_there - m.mid_here as gap,$tr9$,
  $tr10$    select p.good_id, p.port_id, p.nm, p.hops
      from pairs p$tr10$,
  $tr11$    select p.good_id, p.port_id, p.nm
      from pairs p$tr11$,
  $tr12$    select k.good_id, k.port_id, k.nm, k.hops,$tr12$,
  $tr13$    select k.good_id, k.port_id, k.nm,$tr13$,
  $tr14$             'nm', b.nm, 'legs', b.hops,$tr14$,
  $tr15$             'nm', b.nm,$tr15$,
  $tr16$       'max_legs', case when p_to is null then v_legs else null end,$tr16$,
  $tr17$       'radius_nm', case when p_to is null then v_radius else null end,$tr17$);
revoke all on function world.trade_routes(uuid, uuid, numeric, int, uuid) from public, anon;
grant execute on function world.trade_routes(uuid, uuid, numeric, int, uuid) to authenticated;

-- ── 14. THE HELM ORDER AT SEA: she turns where she is ──────────────────────────────────────────
create or replace function cmd.divert(p_fleet uuid, p_dest uuid, p_dest_point jsonb, p_path jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
-- Supersedes 0037's node-turn body (dropped above). Under the free sea she turns AT HER CLOSED-
-- FORM POSITION: the sailing voyage is truncated there and settled through the ONE arrival arm
-- (she comes to anchor at the cut point), the queue composed for the old market is cleared
-- (0037's rule kept), and the onward passage is a plain SAIL through the ONE parser and the ONE
-- mover, from the very point she holds. What has happened stays happened: kept segments are
-- byte-identical, settled days keep their PK, and the onward water is a NEW voyage.
--
-- THE BRIDGE: the client plotted from the position it last READ, and at 1 real minute = 8 sim
-- hours she has moved since. Rather than refuse honest staleness — or teleport her onto the
-- course — her TRUE position is prepended when the course starts more than course_join_nm away,
-- and the bridging water is then verified like all the rest: a cape she rounded between reads
-- refuses the divert instead of sailing her back through it.
declare
  v_player uuid := public.current_player_id();
  v_now    timestamptz := now();
  f  public.fleets%rowtype;
  v  public.voyages%rowtype;
  pos record;
  v_dest_c text;
  v_token  text;
  v_keep   jsonb := '[]'::jsonb;
  v_prof   jsonb := '[]'::jsonb;
  v_acc    numeric := 0;
  v_pnm    numeric;
  i        int := 0;
  e        jsonb;
  v_eta    timestamptz;
  v_issue  jsonb;
  v_course jsonb;
begin
  select * into f from public.fleets where id = p_fleet;
  if f.id is null or v_player is null or f.player_id <> v_player then
    return jsonb_build_object('ok', false, 'error_code', 'E_NO_SUCH_FLEET',
      'error_message', 'That fleet is not yours.', 'fixes', '[]'::jsonb);
  end if;

  -- Catch up first: an act must not reason about a stale position (D.2).
  perform voyage.settle(p_fleet, v_now);
  select * into f from public.fleets where id = p_fleet;
  if f.status <> 'SAILING' then
    return jsonb_build_object('ok', false, 'error_code', 'E_NOT_SAILING',
      'error_message', format('%s is %s, not under way - from a quay, SAIL is the order.', f.name, f.status),
      'fixes', jsonb_build_array(format('SAIL %s TO <the new port>', f.name)));
  end if;

  if p_dest is not null then
    select code into v_dest_c from public.ports where id = p_dest;
    if v_dest_c is null then
      return jsonb_build_object('ok', false, 'error_code', 'E_NO_SUCH_PORT',
        'error_message', 'There is no such port to make for.', 'fixes', '[]'::jsonb);
    end if;
    v_token := v_dest_c;
  elsif p_dest_point is not null
        and jsonb_typeof(p_dest_point->'lat') = 'number' and jsonb_typeof(p_dest_point->'lon') = 'number' then
    v_token := format('%s,%s', round((p_dest_point->>'lat')::numeric, 4), round((p_dest_point->>'lon')::numeric, 4));
    v_dest_c := v_token;
  else
    return jsonb_build_object('ok', false, 'error_code', 'E_NO_SUCH_PORT',
      'error_message', 'Name a port, or a point of open sea.', 'fixes', '[]'::jsonb);
  end if;

  select * into v from public.voyages where fleet_id = p_fleet and status = 'SAILING' for update;
  if p_dest is not null and v.dest_port_id = p_dest then
    return jsonb_build_object('ok', false, 'error_code', 'E_SAME_DEST',
      'error_message', format('%s is already bound for %s.', f.name,
        (select name from public.ports where id = p_dest)),
      'fixes', '[]'::jsonb);
  end if;

  select * into pos from voyage.position(v.id, v_now);

  -- the queue was composed for another market (0037's rule, kept) - and it is cleared BEFORE
  -- she comes to rest, or the arrival arm's own queue-run would depart her on a stale order
  -- in the very same act (found by this file's probe: a pending SAIL took her straight back
  -- out of the anchor before the onward order could be issued).
  perform cmd.clear(p_fleet);

  if pos.nm_done < 1 then
    -- She has barely left: the voyage is unmade whole rather than truncated to nothing
    -- (total_nm must stay > 0). She stands again exactly where she departed.
    update public.voyages set status = 'ABORTED' where id = v.id;
    if v.origin_port_id is not null then
      update public.fleets set status = 'DOCKED', port_id = v.origin_port_id, lat = null, lon = null,
             version = version + 1 where id = p_fleet;
    else
      update public.fleets set status = 'ANCHORED', port_id = null,
             lat = (v.path->0->'a'->>0)::numeric, lon = (v.path->0->'a'->>1)::numeric,
             version = version + 1 where id = p_fleet;
    end if;
  else
    -- Truncate at her position: kept segments byte-identical, the one under her keel cut AT the
    -- point, the unsailed tail gone. total = exactly her progress, so the recomputed ETA is the
    -- instant she holds, and the settle below arrives her THROUGH the one arrival arm.
    for e in select * from jsonb_array_elements(v.path) loop
      exit when i > pos.seg_index;
      if i < pos.seg_index then
        v_keep := v_keep || e;
        v_prof := v_prof || (v.speed_profile->i);
        v_acc  := v_acc + (e->>'nm')::numeric;
      else
        v_pnm := round(pos.nm_done - v_acc, 2);
        if v_pnm > 0 then
          v_keep := v_keep || (e || jsonb_build_object('b', jsonb_build_array(pos.lat, pos.lon), 'nm', v_pnm));
          v_prof := v_prof || (v.speed_profile->i);
        end if;
      end if;
      i := i + 1;
    end loop;
    update public.voyages
       set path = v_keep, speed_profile = v_prof,
           total_nm = (select sum((s->>'nm')::numeric) from jsonb_array_elements(v_keep) s),
           dest_port_id = null
     where id = v.id;
    v_eta := voyage.recompute_eta(v.id);
    perform voyage.settle(p_fleet, greatest(v_now, v_eta));
  end if;

  select * into f from public.fleets where id = p_fleet;
  if f.status not in ('DOCKED', 'ANCHORED') then
    raise exception 'E_DIVERT_FAILED: she did not come to rest at the turn (status %)', f.status using errcode = 'P0001';
  end if;

  -- the bridge, then the onward passage through the ONE parser and the ONE mover
  v_course := p_path;
  if v_course is not null and jsonb_typeof(v_course) = 'array' and jsonb_array_length(v_course) >= 1
     and f.lat is not null
     and voyage.gc_distance_nm(f.lat::float8, f.lon::float8,
           (v_course->0->>0)::float8, (v_course->0->>1)::float8) > public.wc_num('course_join_nm') then
    v_course := jsonb_build_array(jsonb_build_array(f.lat, f.lon)) || v_course;
  end if;
  v_issue := cmd.issue(p_fleet, 'SAIL TO ' || v_token, null, v_course);
  if coalesce(v_issue->>'ok', 'false') <> 'true' then
    -- 7C: a half-made turn (voyage truncated, no onward order) is not an acceptable else.
    -- Raising rolls the WHOLE act back, truncation included; a refused divert changes nothing.
    raise exception 'E_DIVERT_FAILED: the onward order was refused - %',
      coalesce(v_issue->>'error_message', 'no reason given') using errcode = 'P0001';
  end if;

  perform public.emit_event(f.player_id, 'DIVERTED', jsonb_build_object(
    'fleet', f.name, 'voyage_id', v.id,
    'at', format('%s,%s', round(pos.lat, 4), round(pos.lon, 4)),
    'was', coalesce((select code from public.ports where id = v.dest_port_id), 'open sea'),
    'now', v_dest_c, 'queue_cleared', true));

  return jsonb_build_object('ok', true,
    'at', format('%s,%s', round(pos.lat, 4), round(pos.lon, 4)),
    'was', coalesce((select code from public.ports where id = v.dest_port_id), 'open sea'),
    'dest', v_dest_c, 'queue', cmd.queue(p_fleet));
end $$;

comment on function cmd.divert(uuid, uuid, jsonb, jsonb) is
  'THE helm order at sea (0047): truncate the sailing voyage at her closed-form position, settle '
  'her to anchor through the one arrival arm, clear the stale queue, and depart the onward '
  'passage through the one parser and the one mover — bridged to her true position and verified '
  'as water like every other course. Supersedes 0037''s node turn.';

revoke all on function cmd.divert(uuid, uuid, jsonb, jsonb) from public, anon;
grant execute on function cmd.divert(uuid, uuid, jsonb, jsonb) to authenticated;

-- ── 15. The reads the free sea needs ───────────────────────────────────────────────────────────
create or replace function world.sea_raster()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- The one raster, served whole (~346 KB of base64, fetched once per session and cached): the
  -- client's pathfinder PROPOSES over exactly the water the server judges by, because both hold
  -- this row. Lying about it gains nothing - the server re-samples every course it is sent.
  select jsonb_build_object('cols', r.cols, 'rows', r.rows, 'cell_deg', r.cell_deg,
                            'bits_per_cell', r.bits_per_cell,
                            'cells_base64', replace(encode(r.cells, 'base64'), e'\n', ''))
    from public.sea_raster r where r.id = 1
$$;

revoke all on function world.sea_raster() from public, anon;
grant execute on function world.sea_raster() to authenticated;

create or replace function world.reach(p_from uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- One place's sailed distances to everywhere: the SAIL picker's ordering and figures, priced
  -- by the same table the trade scan and the endurance gate read.
  select jsonb_build_object('from', sr.code, 'snap_nm', sr.snap_nm, 'reaches', sr.reaches)
    from public.sea_reaches sr where sr.port_id = p_from
$$;

revoke all on function world.reach(uuid) from public, anon;
grant execute on function world.reach(uuid) to authenticated;

-- ── 16. The client entry points — re-cut whole (supersedes 0037's) ─────────────────────────────
-- Changed rows only: issue/preview gain p_path, divert takes (dest, dest_point, path),
-- trade_routes' third argument is a radius in nm, and the two free-sea reads join the list.
create or replace function public.client_rpc_entry_points()
returns table (schema_name text, function_name text, arg_types text, fn regprocedure)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select t.s, t.f, t.a,
         to_regprocedure(format('%I.%I(%s)', t.s, t.f, t.a))
    from (values
      -- the reads (world)
      ('world'::text, 'snapshot'::text,      ''::text),
      ('world',       'market',              'uuid'),
      ('world',       'fleets',              ''),
      ('world',       'ledger',              'timestamptz, int'),
      ('world',       'buy_capacity',        'uuid, uuid'),
      ('world',       'price_history',       'uuid, int'),
      ('world',       'player',              ''),
      ('world',       'officers',            ''),
      ('world',       'skills',              ''),
      ('world',       'trade_routes',        'uuid, uuid, numeric, int, uuid'),
      ('world',       'haggle_state',        'uuid, uuid'),
      ('world',       'standings',           'int'),
      ('world',       'buffs',               'uuid'),
      ('world',       'provision_presets',   ''),
      -- 0047: the free sea. The raster the client searches, and one place's sailed distances.
      ('world',       'sea_raster',          ''),
      ('world',       'reach',               'uuid'),
      -- the orders (cmd)
      ('cmd',         'issue',               'uuid, text, int, jsonb'),
      ('cmd',         'preview',             'uuid, text, jsonb'),
      ('cmd',         'cancel_at',           'uuid, int'),
      ('cmd',         'clear',               'uuid, boolean'),
      ('cmd',         'verb_schema',         ''),
      ('cmd',         'hire_officer',        'text, uuid'),
      ('cmd',         'post_officer',        'text, uuid'),
      ('cmd',         'study_skill',         'text, uuid'),
      ('cmd',         'found_house',         'text, text'),
      ('cmd',         'haggle',              'uuid, uuid, text'),
      ('cmd',         'provision_preset_save',   'uuid, text, int'),
      ('cmd',         'provision_preset_delete', 'uuid'),
      ('cmd',         'provision_preset_apply',  'uuid, uuid'),
      -- 0047: the helm order at sea - turn where she is, for a port or a bare point of water.
      ('cmd',         'divert',              'uuid, uuid, jsonb, jsonb')
    ) as t(s, f, a)
$$;

-- ── 17. THE LAND GUARD: every stored course, walked ────────────────────────────────────────────
create or replace function voyage.assert_paths_water()
returns table (voyages_walked int, legacy_skipped int)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
-- Walks EVERY stored voyage path at sub-cell intervals through THE one sampler
-- (voyage.path_refusal) and raises on the first sample that is not open water — the owner's law
-- ("i don't want the fleet to ever touch land"), PROVEN rather than intended. Legacy-converted
-- paths (straight port-to-port lines, the old model's shape) are counted and skipped, never
-- silently. Non-vacuity is the CALLER's duty: 0047's probe and proof 08 assert voyages_walked
-- is not zero AND prove the guard bites by feeding it a straight line across Iberia.
declare
  v public.voyages%rowtype;
  v_course jsonb;
  v_ref text;
  v_head numeric;
  v_tail numeric;
  n_walked int := 0;
  n_legacy int := 0;
begin
  for v in select * from public.voyages loop
    if v.path->0 ? 'legacy' then
      n_legacy := n_legacy + 1;
      continue;
    end if;
    v_course := voyage.course_of(v.path);
    -- the same allowances the mover granted: a port's measured snap, or — for an open-water
    -- end — the point's own measured snap (a divert can lawfully cut a course inside a port's
    -- approach, and the guard must judge by the rule the voyage was admitted under).
    v_head := coalesce((select sr.snap_nm from public.sea_reaches sr where sr.port_id = v.origin_port_id),
                       voyage.water_snap_nm((v_course->0->>0)::numeric, (v_course->0->>1)::numeric)) + 25;
    v_tail := coalesce((select sr.snap_nm from public.sea_reaches sr where sr.port_id = v.dest_port_id),
                       voyage.water_snap_nm((v_course->(jsonb_array_length(v_course)-1)->>0)::numeric,
                                            (v_course->(jsonb_array_length(v_course)-1)->>1)::numeric)) + 25;
    v_ref := voyage.path_refusal(v_course,
               (v_course->0->>0)::numeric, (v_course->0->>1)::numeric,
               (v_course->(jsonb_array_length(v_course)-1)->>0)::numeric,
               (v_course->(jsonb_array_length(v_course)-1)->>1)::numeric,
               1, v_head, v_tail);
    if v_ref is not null then
      raise exception 'LAND GUARD: voyage % (% -> %) fails the water law: %',
        v.id,
        coalesce((select code from public.ports where id = v.origin_port_id), 'open sea'),
        coalesce((select code from public.ports where id = v.dest_port_id), 'open sea'),
        v_ref;
    end if;
    n_walked := n_walked + 1;
  end loop;
  voyages_walked := n_walked;
  legacy_skipped := n_legacy;
  return next;
end $$;

revoke all on function voyage.assert_paths_water() from public, anon, authenticated;

comment on function voyage.assert_paths_water() is
  'THE land guard (0047): walks every stored voyage course at sub-cell intervals through '
  'voyage.path_refusal and raises on the first land sample. Callers must assert voyages_walked '
  '> 0 - a guard over an empty set is decoration - and proof 08 break-tests it on every run.';

-- ── SELF-ASSERT ────────────────────────────────────────────────────────────────────────────────
do $$
declare
  c_probe  constant uuid := '00000000-0047-4000-8000-000000000001';
  c_other  constant uuid := '00000000-0047-4000-8000-000000000002';
  v_course_cad  constant jsonb := '[[38.71,-9.14],[36.875,-9.125],[36.625,-8.875],[36.53,-6.3]]'::jsonb;
  v_course_home constant jsonb := '[[36.53,-6.3],[36.625,-8.875],[36.875,-9.125],[38.71,-9.14]]'::jsonb;
  v_course_pt   constant jsonb := '[[38.71,-9.14],[33,-15]]'::jsonb;
  v_course_back constant jsonb := '[[33,-15],[38.71,-9.14]]'::jsonb;
  v_course_sal  constant jsonb := '[[38.71,-9.14],[-9.625,-35.125],[-12.625,-37.875],[-12.98,-38.49]]'::jsonb;
  v_course_turn constant jsonb := '[[36.875,-9.125],[36.625,-8.875],[36.53,-6.3]]'::jsonb;
  v_straight_bcn constant jsonb := '[[38.71,-9.14],[41.38,2.18]]'::jsonb;
  v_lis uuid; v_cad uuid; v_sal uuid; v_bcn uuid; v_pdl uuid;
  v_player uuid; v_other uuid; v_fleet uuid;
  v_res jsonb; v_fpay jsonb; v_routes jsonb;
  v public.voyages%rowtype;
  v_voyage uuid; v_old_total numeric; v_seg0 jsonb;
  v_land_msg text; v_guard_msg text;
  v_nm numeric; v_reach numeric; v_n int; v_i int;
  v_leg record; v_conv uuid; v_sim0 numeric; v_sim1 numeric;
  g record;
  v_good text;
begin
  select id into v_lis from public.ports where code = 'LIS';
  select id into v_cad from public.ports where code = 'CAD';
  select id into v_sal from public.ports where code = 'SLV';
  select id into v_bcn from public.ports where code = 'BAR';
  select id into v_pdl from public.ports where code = 'PON';
  select code into v_good from public.goods order by code limit 1;

  begin
    v_player := public.new_house(c_probe, 'Casa do Mar Livre', 'PRT');
    perform cmd.assume_identity(c_probe);
    select id into v_fleet from public.fleets where player_id = v_player;
    -- the probe owns its preconditions: watered, fed, fully crewed (README section 3)
    perform cmd.do_provision(v_fleet, jsonb_build_object('mode', 'FULL'));
    perform cmd.do_hire(v_fleet, jsonb_build_object('count',
      (select c.crew_max - sh.crew from public.ships sh
         join public.ship_classes c on c.id = sh.class_id where sh.fleet_id = v_fleet)));

    -- (a) THE LAW BITES THROUGH THE ONE ENTRY: a straight course across Iberia is refused E_LAND.
    v_res := cmd.issue(v_fleet, 'SAIL TO BAR', null, v_straight_bcn);
    if v_res->>'error_code' is distinct from 'E_LAND' then
      raise exception '0047 self-assert FAIL: a straight Lisbon-Barcelona course through cmd.issue was not refused E_LAND (got [%: %])',
        v_res->>'error_code', v_res->>'error_message';
    end if;
    v_land_msg := v_res->>'error_message';
    perform cmd.clear(v_fleet);

    -- (b) NO COURSE, NO GUESS: Lisbon-Cadiz straight is not water, so an unplotted SAIL refuses
    v_res := cmd.issue(v_fleet, 'SAIL TO CAD');
    if v_res->>'error_code' is distinct from 'E_NO_COURSE' then
      raise exception '0047 self-assert FAIL: an unplotted SAIL round a cape was not refused E_NO_COURSE (got [%])', v_res->>'error_code';
    end if;
    perform cmd.clear(v_fleet);

    -- (c) a course that joins the wrong water is refused as itself
    v_res := cmd.issue(v_fleet, 'SAIL TO CAD', null, v_course_pt);
    if v_res->>'error_code' is distinct from 'E_OFF_COURSE' then
      raise exception '0047 self-assert FAIL: a course ending 500 nm from the destination was not refused E_OFF_COURSE (got [%])', v_res->>'error_code';
    end if;
    perform cmd.clear(v_fleet);

    -- (d) THE MOVER: the real water course departs her, measured by the server
    v_res := cmd.issue(v_fleet, 'SAIL TO CAD', null, v_course_cad);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0047 self-assert FAIL: the real Lisbon-Cadiz course was refused: [%: %]',
        v_res->>'error_code', v_res->>'error_message';
    end if;
    select * into v from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    select sum((s->>'nm')::numeric) into v_nm from jsonb_array_elements(v.path) s;
    select (reaches->>'CAD')::numeric into v_reach from public.sea_reaches where code = 'LIS';
    if abs(v.total_nm - v_nm) > 0.05 then
      raise exception '0047 self-assert FAIL: total_nm % is not the sum of its own segments %', v.total_nm, v_nm;
    end if;
    if abs(v.total_nm - v_reach) > v_reach * 0.03 then
      raise exception '0047 self-assert FAIL: the sailed course measures % nm but the reach table quotes % - the quay and the water disagree', v.total_nm, v_reach;
    end if;
    if jsonb_array_length(v.speed_profile) <> jsonb_array_length(v.path)
       or v.origin_port_id <> v_lis or v.dest_port_id <> v_cad then
      raise exception '0047 self-assert FAIL: the voyage row is misshapen (profile %, path %, origin %, dest %)',
        jsonb_array_length(v.speed_profile), jsonb_array_length(v.path), v.origin_port_id, v.dest_port_id;
    end if;
    if voyage.progress_nm(v.id, v.departed_at) <> 0
       or voyage.progress_nm(v.id, v.eta) < v.total_nm - 0.01 then
      raise exception '0047 self-assert FAIL: progress is not closed-form over the new path shape';
    end if;

    -- (e) THE WIRE: the whole course, the anchorless position, the destination code
    select f into v_fpay from jsonb_array_elements(world.fleets()) f where f->>'id' = v_fleet::text;
    if jsonb_array_length(v_fpay->'voyage'->'course') <> jsonb_array_length(v.path) + 1
       or v_fpay->'voyage'->>'to' is distinct from 'CAD'
       or (v_fpay->'voyage'->'position'->>'lat') is null
       or (v_fpay->'voyage'->'position'->>'lon') is null then
      raise exception '0047 self-assert FAIL: world.fleets does not serve the course and the position (voyage payload: %)', v_fpay->'voyage';
    end if;

    -- (f) THE QUEUE CARRIES ON ACROSS AN ARRIVAL: a homeward SAIL queued at sea departs itself
    v_res := cmd.issue(v_fleet, 'SAIL TO LIS', null, v_course_home);
    if (select count(*) from public.orders where fleet_id = v_fleet and status = 'pending') <> 1 then
      raise exception '0047 self-assert FAIL: the homeward SAIL did not queue while she was at sea';
    end if;
    v_i := 0;
    while (select status from public.fleets where id = v_fleet) <> 'DOCKED' and v_i < 20 loop
      update public.voyages set departed_at = departed_at - interval '600 hours', eta = eta - interval '600 hours'
       where fleet_id = v_fleet and status = 'SAILING';
      perform voyage.settle(v_fleet);
      v_i := v_i + 1;
      exit when (select port_id from public.fleets where id = v_fleet) = v_lis;
    end loop;
    if (select port_id from public.fleets where id = v_fleet) is distinct from v_lis then
      raise exception '0047 self-assert FAIL: the queued homeward SAIL did not carry her back to LIS (at %, status %)',
        (select coalesce(p.code, 'nowhere') from public.fleets fl left join public.ports p on p.id = fl.port_id where fl.id = v_fleet),
        (select status from public.fleets where id = v_fleet);
    end if;
    perform cmd.do_provision(v_fleet, jsonb_build_object('mode', 'FULL'));

    -- (g) PINPOINT: any water point is a destination, and she ANCHORS there
    v_res := cmd.issue(v_fleet, 'SAIL TO 33,-15', null, v_course_pt);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0047 self-assert FAIL: the pinpoint SAIL was refused: [%: %]', v_res->>'error_code', v_res->>'error_message';
    end if;
    select * into v from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v.dest_port_id is not null then
      raise exception '0047 self-assert FAIL: a pinpoint voyage minted a destination port';
    end if;
    update public.voyages set departed_at = departed_at - interval '600 hours', eta = eta - interval '600 hours'
     where id = v.id;
    perform voyage.settle(v_fleet);
    if (select status from public.fleets where id = v_fleet) <> 'ANCHORED'
       or (select lat from public.fleets where id = v_fleet) <> 33
       or (select lon from public.fleets where id = v_fleet) <> -15 then
      raise exception '0047 self-assert FAIL: she did not come to ANCHOR at 33,-15 (status %, lat %, lon %)',
        (select status from public.fleets where id = v_fleet),
        (select lat from public.fleets where id = v_fleet),
        (select lon from public.fleets where id = v_fleet);
    end if;
    if not exists (select 1 from public.events ev where ev.player_id = v_player and ev.kind = 'VOYAGE_REPORT'
                    and ev.payload->'to' = 'null'::jsonb and ev.payload->'to_point' = '[33, -15]'::jsonb) then
      raise exception '0047 self-assert FAIL: the open-water arrival report does not carry the point (no to_point [33,-15])';
    end if;
    -- the quay verbs refuse her at anchor, as themselves
    v_res := cmd.issue(v_fleet, format('BUY %s 1', v_good));
    if v_res->>'error_code' is distinct from 'E_NOT_DOCKED' then
      raise exception '0047 self-assert FAIL: BUY at open anchor was not refused E_NOT_DOCKED (got [%])', v_res->>'error_code';
    end if;
    perform cmd.clear(v_fleet);

    -- (h) ...and she can always leave: home from the anchor, through the same one mover
    v_res := cmd.issue(v_fleet, 'SAIL TO LIS', null, v_course_back);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0047 self-assert FAIL: the SAIL home from open anchor was refused: [%: %]', v_res->>'error_code', v_res->>'error_message';
    end if;
    select * into v from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v.origin_port_id is not null then
      raise exception '0047 self-assert FAIL: a voyage from open anchor minted an origin port';
    end if;
    update public.voyages set departed_at = departed_at - interval '600 hours', eta = eta - interval '600 hours'
     where id = v.id;
    perform voyage.settle(v_fleet);
    if (select port_id from public.fleets where id = v_fleet) is distinct from v_lis then
      raise exception '0047 self-assert FAIL: she did not dock home from the anchor';
    end if;

    -- (i) THE ONE-WAY TRAP IS REFUSED: thin stores cannot buy a passage to nowhere
    update public.ships set water_t = 1, food_t = 1 where fleet_id = v_fleet;
    v_res := cmd.issue(v_fleet, 'SAIL TO 33,-15', null, v_course_pt);
    if v_res->>'error_code' is distinct from 'E_ENDURANCE'
       or position('round trip' in coalesce(v_res->>'error_message', '')) = 0 then
      raise exception '0047 self-assert FAIL: a thin-stores pinpoint SAIL was not refused for the ROUND TRIP (got [%: %])',
        v_res->>'error_code', v_res->>'error_message';
    end if;
    perform cmd.clear(v_fleet);
    perform cmd.do_provision(v_fleet, jsonb_build_object('mode', 'FULL'));

    -- (j) THE HELM: she turns where she is. The probe owns its preconditions (README section 3):
    -- the passages behind her may have cost crew, hull and coin to the dice, and a slower,
    -- thirstier fleet was refused this 3,500 nm passage on some runs and not others. The helm
    -- test is about the TURN, not the larder or the surgeon, so she is made whole first.
    update public.ships s set crew = c.crew_max, durability = c.durability
      from public.ship_classes c where c.id = s.class_id and s.fleet_id = v_fleet;
    update public.players set ducats = 8000 where id = v_player;
    -- stores are SET, not bought: do_provision(FULL) raises E_HOLD_FULL when the casks are
    -- already topped, and whether they are depends on the run's dice. 45 crew-days of each is
    -- deterministic and comfortably clears the 3,500 nm passage's margin.
    update public.ships s
       set water_t = round(s.crew * public.wc_num('water_per_crew_day') * 45, 3),
           food_t  = round(s.crew * public.wc_num('food_per_crew_day') * 45, 3)
     where s.fleet_id = v_fleet;
    v_res := cmd.issue(v_fleet, 'SAIL TO SLV', null, v_course_sal);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0047 self-assert FAIL: the Salvador passage was refused: [%: %]', v_res->>'error_code', v_res->>'error_message';
    end if;
    select * into v from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    v_voyage := v.id; v_old_total := v.total_nm; v_seg0 := v.path->0;
    -- put her ten sim-hours out — DERIVED from time_compression (0045 made it 9600: ten
    -- sim-hours is 3.75 real seconds; at the old 480 it was 75), so this probe cannot break
    -- again the next time the clock changes: mid-first-segment, day 1 unsettled
    update public.voyages set departed_at = departed_at - make_interval(secs => (10 * 3600 / public.wc_num('time_compression'))::double precision),
                              eta = eta - make_interval(secs => (10 * 3600 / public.wc_num('time_compression'))::double precision)
     where id = v_voyage;
    -- something pending, composed for the old destination, so the clearing is provable
    perform cmd.issue(v_fleet, 'SAIL TO PON');
    -- the refusals, while she is under way
    v_res := cmd.divert(v_fleet, v_sal, null, null);
    if v_res->>'error_code' is distinct from 'E_SAME_DEST' then
      raise exception '0047 self-assert FAIL: diverting to her own destination was not E_SAME_DEST (got [%])', v_res->>'error_code';
    end if;
    v_res := cmd.divert(v_fleet, '00000000-0047-4000-8000-00000000dead', null, null);
    if v_res->>'error_code' is distinct from 'E_NO_SUCH_PORT' then
      raise exception '0047 self-assert FAIL: diverting to a made-up port was not E_NO_SUCH_PORT (got [%])', v_res->>'error_code';
    end if;
    v_other := public.new_house(c_other, 'Casa Alheia', 'PRT');
    perform cmd.assume_identity(c_other);
    v_res := cmd.divert(v_fleet, v_cad, null, v_course_turn);
    perform cmd.assume_identity(c_probe);
    if v_res->>'error_code' is distinct from 'E_NO_SUCH_FLEET' then
      raise exception '0047 self-assert FAIL: another captain took her helm (got [%])', coalesce(v_res->>'error_code', 'ok');
    end if;
    -- THE TURN, bridged to her true position and verified as water
    v_res := cmd.divert(v_fleet, v_cad, null, v_course_turn);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0047 self-assert FAIL: the divert itself was refused: [%: %]', v_res->>'error_code', v_res->>'error_message';
    end if;
    select * into v from public.voyages where id = v_voyage;
    if v.status <> 'ARRIVED' or v.dest_port_id is not null
       or v.total_nm >= v_old_total or v.total_nm < 1
       or v.path->0->'a' is distinct from v_seg0->'a' then
      raise exception '0047 self-assert FAIL: the truncation is wrong (status %, dest %, total % of old %, seg0 moved: %)',
        v.status, v.dest_port_id, v.total_nm, v_old_total, (v.path->0->'a' is distinct from v_seg0->'a');
    end if;
    select * into v from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v.id is null or v.id = v_voyage or v.origin_port_id is not null or v.dest_port_id is distinct from v_cad then
      raise exception '0047 self-assert FAIL: the onward passage is not a NEW voyage from her position to CAD';
    end if;
    if voyage.gc_distance_nm((v.path->0->'a'->>0)::float8, (v.path->0->'a'->>1)::float8,
         (select lat from voyage.position(v_voyage, now()))::float8,
         (select lon from voyage.position(v_voyage, now()))::float8) > 20 then
      raise exception '0047 self-assert FAIL: the onward course does not begin where she turned';
    end if;
    if (select count(*) from public.orders where fleet_id = v_fleet and status = 'cancelled' and raw_text = 'SAIL TO PON') <> 1 then
      raise exception '0047 self-assert FAIL: the stale queue was not cleared by the turn';
    end if;
    if not exists (select 1 from public.events ev where ev.player_id = v_player and ev.kind = 'DIVERTED'
                    and ev.payload->>'now' = 'CAD') then
      raise exception '0047 self-assert FAIL: no DIVERTED ledger line names the turn';
    end if;
    update public.voyages set departed_at = departed_at - interval '600 hours', eta = eta - interval '600 hours'
     where fleet_id = v_fleet and status = 'SAILING';
    perform voyage.settle(v_fleet);
    if (select port_id from public.fleets where id = v_fleet) is distinct from v_cad then
      raise exception '0047 self-assert FAIL: the onward passage did not dock her at CAD';
    end if;
    v_res := cmd.divert(v_fleet, v_lis, null, null);
    if v_res->>'error_code' is distinct from 'E_NOT_SAILING' then
      raise exception '0047 self-assert FAIL: a docked fleet answered her helm (got [%])', coalesce(v_res->>'error_code', 'ok');
    end if;

    -- (k) THE CARRY-FORWARD, non-vacuous: an old-shape voyage converts and its schedule holds
    select l.id, l.from_port_id, l.to_port_id, l.distance_nm, l.hazard_mult,
           (select sea_id from public.ports where id = l.to_port_id) as sea_id
      into v_leg
      from public.legs l
     where l.from_port_id = v_lis or l.to_port_id = v_lis
     order by l.distance_nm, l.id limit 1;
    insert into public.voyages (fleet_id, player_id, path, total_nm, speed_profile,
                                departed_at, eta, status, last_settled_day, origin_port_id, dest_port_id)
    values (v_fleet, v_player,
            jsonb_build_array(jsonb_build_object('leg_id', v_leg.id, 'from_id', v_leg.from_port_id,
              'to_id', v_leg.to_port_id, 'nm', v_leg.distance_nm, 'hazard_mult', v_leg.hazard_mult,
              'sea_id', v_leg.sea_id)),
            v_leg.distance_nm, '[4.5]'::jsonb,
            now() - interval '1 day', now() - interval '1 hour', 'ARRIVED', 1,
            v_leg.from_port_id, v_leg.to_port_id)
    returning id into v_conv;
    v_sim0 := voyage.sim_hours(v_conv);
    update public.voyages set path = voyage.convert_leg_path(path) where id = v_conv;
    v_sim1 := voyage.sim_hours(v_conv);
    select * into v from public.voyages where id = v_conv;
    if not (v.path->0 ? 'legacy') or v_sim0 is distinct from v_sim1
       or v.path->0->'a'->>0 is distinct from (select lat::text from public.ports where id = v_leg.from_port_id)
       or v.path->0->>'sea_id' is distinct from v_leg.sea_id::text then
      raise exception '0047 self-assert FAIL: the leg-path conversion changed the contract (legacy %, sim % -> %, a %, sea %)',
        v.path->0 ? 'legacy', v_sim0, v_sim1, v.path->0->'a', v.path->0->>'sea_id';
    end if;

    -- (l) THE LAND GUARD walks the probe's own wake, and BITES on a planted straight line
    select * into g from voyage.assert_paths_water();
    if g.voyages_walked < 4 or g.legacy_skipped < 1 then
      raise exception '0047 self-assert FAIL: the land guard walked % voyage(s) and skipped % legacy - it is asserting over too little to mean anything',
        g.voyages_walked, g.legacy_skipped;
    end if;
    insert into public.voyages (fleet_id, player_id, path, total_nm, speed_profile,
                                departed_at, eta, status, last_settled_day, origin_port_id, dest_port_id)
    values (v_fleet, v_player, voyage.segments_from_course(v_straight_bcn),
            (select sum((s->>'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(v_straight_bcn)) s),
            '[4.5, 4.5]'::jsonb, now() - interval '1 day', now() - interval '1 hour', 'ARRIVED', 1, v_lis, v_bcn);
    begin
      perform * from voyage.assert_paths_water();
      raise exception '0047 self-assert FAIL: the land guard swallowed a straight Lisbon-Barcelona voyage whole - it cannot catch anything';
    exception when others then
      if sqlerrm like '0047 self-assert FAIL%' then raise; end if;
      v_guard_msg := sqlerrm;
      if position('E_LAND' in v_guard_msg) = 0 then
        raise exception '0047 self-assert FAIL: the land guard refused the planted voyage for the wrong reason: %', v_guard_msg;
      end if;
    end;

    -- (m) THE QUAY AND THE WATER AGREE: every recommended run is priced at the reach table's nm
    perform cmd.assume_identity(c_probe);
    v_res := world.trade_routes(v_lis, null, null, null);
    if jsonb_array_length(v_res->'routes') < 1 then
      raise exception '0047 self-assert FAIL: the trade scan found nothing within % nm of Lisbon', v_res->'basis'->>'radius_nm';
    end if;
    select count(*) into v_n
      from jsonb_array_elements(v_res->'routes') rr
     where (rr->>'nm')::numeric is distinct from
           (select (reaches->>(rr->'to'->>'code'))::numeric from public.sea_reaches where code = 'LIS');
    if v_n <> 0 then
      raise exception '0047 self-assert FAIL: % trade route(s) are not priced at the reach table''s sailed nm', v_n;
    end if;
    if (v_res->'basis'->>'radius_nm')::numeric is distinct from public.wc_num('sea_scan_radius_nm')
       or v_res->'routes'->0 ? 'legs' then
      raise exception '0047 self-assert FAIL: the scan basis does not state its radius, or rows still carry graph hops';
    end if;

    raise exception '__PROBE_ROLLBACK__' using errcode = 'P0001';
  exception when others then
    if sqlerrm <> '__PROBE_ROLLBACK__' then raise; end if;
  end;

  if (select count(*) from public.players where auth_uid in (c_probe, c_other)) <> 0 then
    raise exception '0047 self-assert FAIL: probe house(s) survived the subtransaction';
  end if;

  -- (n) ONE MOVER: the graph authorities are GONE, not joined
  if to_regprocedure('voyage.route(uuid, uuid, uuid[])') is not null
     or to_regprocedure('voyage.route_direct(uuid, uuid)') is not null
     or to_regprocedure('voyage.path_from_nodes(uuid[])') is not null
     or to_regprocedure('voyage.reach_from(uuid, int, uuid)') is not null
     or to_regprocedure('voyage.sail_refusal(uuid, uuid, numeric)') is not null
     or to_regprocedure('voyage.depart(uuid, uuid[], timestamptz)') is not null
     or to_regprocedure('cmd.divert(uuid, uuid)') is not null
     or to_regprocedure('cmd.issue(uuid, text, int)') is not null
     or to_regprocedure('cmd.preview(uuid, text)') is not null
     or to_regprocedure('world.trade_routes(uuid, uuid, int, int, uuid)') is not null then
    raise exception '0047 self-assert FAIL: a graph-era movement authority still exists - the catastrophe was four overlapping movement paths, and this file exists to leave ONE';
  end if;

  -- (o) the wire and the wall
  if exists (select 1 from public.client_rpc_entry_points() e where e.fn is null)
     or not has_function_privilege('authenticated', 'cmd.issue(uuid, text, int, jsonb)', 'execute')
     or has_function_privilege('anon', 'cmd.issue(uuid, text, int, jsonb)', 'execute')
     or not has_function_privilege('authenticated', 'cmd.divert(uuid, uuid, jsonb, jsonb)', 'execute')
     or not has_function_privilege('authenticated', 'world.sea_raster()', 'execute')
     or not has_function_privilege('authenticated', 'world.reach(uuid)', 'execute')
     or has_function_privilege('anon', 'world.sea_raster()', 'execute')
     or (select count(*) from public.client_write_grants()) <> 0
     or (select count(*) from public.client_executable_writers()) <> 0
     or (select count(*) from public.caller_evaluated_functions()) <> 0 then
    raise exception '0047 self-assert FAIL: the posture is wrong - an entry point does not resolve, a grant is missing or excessive, or the read wall no longer reads zero';
  end if;

  if (world.snapshot()) ? 'legs' then
    raise exception '0047 self-assert FAIL: world.snapshot still serves the leg graph';
  end if;
  if not exists (select 1 from jsonb_array_elements(cmd.verb_schema()) vb
                  where vb->>'verb' = 'SAIL'
                    and vb->'args'->1->>'type' = 'place'
                    and jsonb_array_length(vb->'args') = 2) then
    raise exception '0047 self-assert FAIL: the served SAIL grammar is not [fleet, place]';
  end if;
  if (world.sea_raster()->>'cols')::int <> (select cols from public.sea_raster)
     or length(world.sea_raster()->>'cells_base64') < 100000 then
    raise exception '0047 self-assert FAIL: world.sea_raster does not serve the raster whole';
  end if;

  raise notice '0047 self-assert ok: THE SEA IS A FREE PLANE and there is ONE MOVER - a real house was refused a straight course across Iberia as E_LAND through cmd.issue itself ("%"), refused an unplotted cape passage E_NO_COURSE, refused a mis-joined course E_OFF_COURSE, and then SAILED: Lisbon-Cadiz on a verified water course whose server-measured total equals its own segments and the reach table''s quote to 3 percent, served whole to the chart (course + closed-form position); a homeward SAIL queued at sea departed itself on arrival; she PINPOINTED 33,-15, ANCHORED on the very point, was refused BUY there as E_NOT_DOCKED, sailed home from the anchor, and with thin stores was refused the same passage for the ROUND TRIP; the helm answered MID-OCEAN - truncated at her position to the mile, stale queue cancelled, a NEW voyage bridged from where she stood to Cadiz, docked, and a docked helm refused E_NOT_SAILING; a leg-era voyage converted with its schedule byte-identical and its legacy mark on; the LAND GUARD walked % voyage(s) (skipping % legacy) and BIT a planted straight Lisbon-Barcelona voyage ("%"); every trade recommendation is priced at the reach table''s sailed nm; the graph authorities are dropped, the catalogue resolves, and the read wall reads zero',
    v_land_msg, g.voyages_walked, g.legacy_skipped, v_guard_msg;
end $$;
